// Verifies the HMAC signature Convex put on the raw request body.
// Secret comes from the environment, never from this workflow.
const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;
const item = $input.first();
const headers = item.json.headers || {};
const timestamp = headers['x-lendloop-timestamp'];
const signature = headers['x-lendloop-signature'] || '';

const raw = item.binary && item.binary.data
  ? (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')
  : '';

function reject(reason) {
  return [{ json: { valid: false, reason } }];
}
if (!raw) return reject('missing raw body');
if (!timestamp || !signature) return reject('missing signature headers');
if (Math.abs(Date.now() / 1000 - Number(timestamp)) > MAX_SKEW_SECONDS) return reject('stale timestamp');

const expected = 'sha256=' + crypto
  .createHmac('sha256', $env.LENDLOOP_SECRET_FROM_CONVEX)
  .update(timestamp + '.' + raw)
  .digest('hex');
const a = Buffer.from(expected);
const b = Buffer.from(signature);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject('bad signature');

const event = JSON.parse(raw);
// Keep only the fields the notification needs.
return [{ json: {
  valid: true,
  eventId: event.eventId,
  type: event.type,
  loan: event.loan,
  tool: event.tool,
  recipient: event.recipient,
  message: event.message, // message.received only
  link: event.link,       // message.received / tool.available / wanted.match
  wanted: event.wanted,   // wanted.match only
} }];

// Convex delivers at least once, so the same event can arrive twice
// (e.g. n8n answered but the response was lost). Skip events already handled.
const seen = $getWorkflowStaticData('global');
seen.eventIds = seen.eventIds || [];
const item = $input.first().json;
return [{ json: { ...item, duplicate: seen.eventIds.includes(item.eventId) } }];

// Mock notification channel: writes the email to the n8n log.
// Swap this node for Email / Slack / Discord without changing anything else.
const e = $input.first().json;
const APP = 'http://localhost:3000';
const MESSAGES = {
  'loan.requested': () => `${e.recipient.name}, someone asked to borrow your ${e.tool.name} (${e.loan.startDate} to ${e.loan.endDate}).`,
  'loan.approved': () => `${e.recipient.name}, your request for the ${e.tool.name} was approved. Pick-up from ${e.loan.startDate}.`,
  'loan.declined': () => `${e.recipient.name}, your request for the ${e.tool.name} was declined.`,
  'loan.cancelled': () => `${e.recipient.name}, a request for your ${e.tool.name} was cancelled.`,
  'loan.returned': () => `${e.recipient.name}, the ${e.tool.name} loan is marked returned. Thanks!`,
  'message.received': () => `${e.recipient.name}, ${e.message.from} sent you a message about the ${e.tool.name}: "${e.message.preview}" Reply: ${APP}${e.link}`,
  'wanted.match': () => `${e.recipient.name}, someone just listed a ${e.tool.name}, which may match your request "${e.wanted.title}". Take a look: ${APP}${e.link}`,
  'tool.available': () => `${e.recipient.name}, the ${e.tool.name} you were waiting for is available again. Request it: ${APP}${e.link}`,
};
const message = MESSAGES[e.type] ? MESSAGES[e.type]() : `Update on the ${e.tool.name}: ${e.type}`;
console.log(`[LendLoop notify] to=${e.recipient.email} event=${e.eventId} ${message}`);
return [{ json: { eventId: e.eventId, channel: 'mock-log', delivered: true } }];

// Record the event only after the notification succeeded, so a failure is retried.
const seen = $getWorkflowStaticData('global');
seen.eventIds = [...(seen.eventIds || []), $input.first().json.eventId].slice(-500);
return $input.all();
